  "implementation": "def solve(case):
    import json
    nodes = case['nodes']
    core = case['core_distance']
    distances = case['distances']
    n = len(nodes)
    if n < 2:
        raise ValueError('Need at least two nodes')
    # Build edge list with mutual reachability
    edges = []
    for u, v, d in distances:
        if u not in core or v not in core:
            raise ValueError('Node not in core_distance')
        # canonical order
        if u > v:
            u, v = v, u
        weight = max(core[u], core[v], d)
        edges.append((weight, u, v))
    # Sort edges: primary weight, then u, then v
    edges.sort(key=lambda e: (e[0], e[1], e[2]))
    # Union-Find
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst_edges = []
    total_weight = 0.0
    for w, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, w])
            total_weight += w
            if len(mst_edges) == n - 1:
                break
    if len(mst_edges) != n - 1:
        raise ValueError('Graph is disconnected')
    return {
        'mst_edges': mst_edges,
        'total_weight': total_weight
    }"
